package main

import (
	"context"
	"flag"
	"fmt"
	"gocode/internal/loop"
	"gocode/internal/model"
	"gocode/internal/session"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"gocode/internal/tool"
	toolexec "gocode/internal/tool/exec"
	toolfile "gocode/internal/tool/file"
	toolwebfetch "gocode/internal/tool/webfetch"
	uiiface "gocode/internal/ui"
	bubbleui "gocode/internal/ui/bubble"
	"gocode/internal/ui/headless"
	"io"
	"log"
	"os"
)

type options struct {
	prompt    string
	sessionID string
}

func parseOptions() options {
	prompt := flag.String("p", "", "single-turn prompt; omit to start Bubble Tea UI")
	sessionID := flag.String("s", "", "session ID; omit to resume/create by cwd")
	flag.Parse()

	return options{
		prompt:    *prompt,
		sessionID: *sessionID,
	}
}

func main() {
	opts := parseOptions()
	ctx := context.Background()

	if opts.prompt != "" {
		if err := runSingleTurnMode(ctx, opts); err != nil {
			log.Fatal(err)
		}
		return
	}

	if err := runInteractiveMode(ctx, opts); err != nil {
		log.Fatal(err)
	}
}

func runSingleTurnMode(ctx context.Context, opts options) error {
	output := headless.New(os.Stdout)
	runner, sessionID, _, _, _, _, err := buildRunner(ctx, opts.sessionID, output)
	if err != nil {
		return err
	}

	fmt.Fprintf(os.Stderr, "session: %s\n", sessionID)
	_, err = runner.RunTurn(ctx, opts.prompt)
	return err
}

func runInteractiveMode(ctx context.Context, opts options) error {
	clearTerminalWindow(os.Stdout)

	output := bubbleui.New()
	runner, sessionID, client, settingsController, subagentManager, store, err := buildRunner(ctx, opts.sessionID, output)
	if err != nil {
		return err
	}

	output.SetModelConfigController(client)
	output.SetSettingsController(settingsController)
	output.SetSubagentController(subagentManager)
	output.SetSessionStore(store)
	return output.Run(ctx, runner, sessionID)
}

func clearTerminalWindow(w io.Writer) {
	if w == nil {
		return
	}
	_, _ = io.WriteString(w, "\x1b[H\x1b[2J\x1b[3J")
}

func buildRunner(ctx context.Context, sessionIDFlag string, output uiiface.UI) (*loop.Runner, string, *model.Client, *settings.Controller, *subagent.Manager, *session.JSONLStore, error) {
	cfg, err := model.LoadConfigFromEnv()
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}

	root, err := os.Getwd()
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}

	store, err := session.NewJSONLStoreInCwd()
	if err != nil {
		return nil, "", nil, nil, nil, nil, fmt.Errorf("初始化 session store 失败: %w", err)
	}

	sessionID, err := resolveSessionID(ctx, store, sessionIDFlag, root)
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}

	client := model.NewClient(cfg)
	settingsController, err := settings.NewControllerInCwd()
	if err != nil {
		return nil, "", nil, nil, nil, nil, err
	}
	var notifier subagent.Notifier
	if n, ok := output.(subagent.Notifier); ok {
		notifier = n
	}
	subagentManager := subagent.NewManager(subagent.Config{
		Model:    client,
		Store:    store,
		Root:     root,
		Settings: settingsController,
		Notifier: notifier,
	})
	registry := tool.NewRegistry()
	registry.Register(&toolfile.LSTool{Root: root})
	registry.Register(&toolfile.ReadTool{Root: root})
	registry.Register(&toolfile.WriteTool{Root: root})
	registry.Register(&toolfile.GrepTool{Root: root})
	registry.Register(&toolfile.GlobTool{Root: root})
	registry.Register(&toolexec.BashTool{Root: root})
	registry.Register(&toolwebfetch.Tool{})
	registry.Register(subagent.NewTool(subagentManager, sessionID))
	registry.Register(subagent.NewStatusTool(subagentManager))

	return loop.NewRunnerWithInstructionRoot(client, output, registry, store, sessionID, root), sessionID, client, settingsController, subagentManager, store, nil
}

func resolveSessionID(ctx context.Context, store *session.JSONLStore, sessionIDFlag, cwd string) (string, error) {
	if sessionIDFlag != "" {
		exists, err := store.Exists(ctx, sessionIDFlag)
		if err != nil {
			return "", fmt.Errorf("查询 session 失败: %w", err)
		}
		if !exists {
			return "", fmt.Errorf("session 不存在: %s", sessionIDFlag)
		}
		return sessionIDFlag, nil
	}

	sessionID, err := session.GenerateSessionID()
	if err != nil {
		return "", fmt.Errorf("生成 session ID 失败: %w", err)
	}
	if _, err := store.CreateRoot(ctx, session.CreateRootRequest{SessionID: sessionID}); err != nil {
		return "", fmt.Errorf("创建 session 失败: %w", err)
	}
	return sessionID, nil
}

package ui

import "encoding/json"

// ToolCallEvent 描述一次工具调用事件。
// UI 只关心展示，因此这里保留最小字段集合。
type ToolCallEvent struct {
	ID    string
	Name  string
	Input json.RawMessage
}

// ToolResultEvent 描述一次工具执行结果事件。
// Name 单独保留一份，避免 UI 还要再从其他结构推断工具名。
type ToolResultEvent struct {
	ToolUseID string
	Name      string
	Content   string
	IsError   bool
}

// SystemEvent 描述由后台任务或控制器产生的系统消息。
type SystemEvent struct {
	Title string
	Body  string
}

// UI 定义 loop 层依赖的最小输出接口。
// 当前既要支持纯文本流式渲染，也要支持工具调用/结果事件展示。
type UI interface {
	OnAssistantDelta(text string) error
	OnToolCall(event ToolCallEvent) error
	OnToolResult(event ToolResultEvent) error
	OnDone() error
}

// ThinkingDeltaReceiver 是 UI 的可选扩展，用于接收模型 thinking 流。
type ThinkingDeltaReceiver interface {
	OnThinkingDelta(text string) error
}

// SystemNotifier 是 UI 的可选扩展，用于接收后台任务完成等系统事件。
type SystemNotifier interface {
	OnSystemMessage(event SystemEvent) error
}

// 本文件定义 TUI 颜色管理器，集中维护主题色和光标颜色。
package bubble

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// colorRole 表示一个可复用的颜色语义角色。
type colorRole string

// 颜色语义角色常量。
const (
	colorTerminalBackground     colorRole = "terminal.background"
	colorHeaderBackground       colorRole = "header.background"
	colorHeaderForeground       colorRole = "header.foreground"
	colorLabelUser              colorRole = "label.user"
	colorLabelAssistant         colorRole = "label.assistant"
	colorLabelTool              colorRole = "label.tool"
	colorLabelSystem            colorRole = "label.system"
	colorLabelError             colorRole = "label.error"
	colorBody                   colorRole = "body"
	colorMarkdownHeading        colorRole = "markdown.heading"
	colorMarkdownRule           colorRole = "markdown.rule"
	colorMarkdownBullet         colorRole = "markdown.bullet"
	colorMarkdownCodeForeground colorRole = "markdown.code.foreground"
	colorMarkdownCodeBackground colorRole = "markdown.code.background"
	colorMarkdownCodeBorder     colorRole = "markdown.code.border"
	colorMarkdownQuote          colorRole = "markdown.quote"
	colorMarkdownQuoteBorder    colorRole = "markdown.quote.border"
	colorPanelBorder            colorRole = "panel.border"
	colorInputFocusedBorder     colorRole = "input.focused.border"
	colorInputWaitingBorder     colorRole = "input.waiting.border"
	colorInputMultilineBorder   colorRole = "input.multiline.border"
	colorInputTerminal          colorRole = "input.terminal"
	colorSelectedProviderBg     colorRole = "provider.selected.background"
	colorSelectedProviderFg     colorRole = "provider.selected.foreground"
	colorUnselectedProvider     colorRole = "provider.unselected"
	colorWizardTitle            colorRole = "wizard.title"
	colorWizardBorder           colorRole = "wizard.border"
	colorSelectionBackground    colorRole = "selection.background"
	colorSelectionForeground    colorRole = "selection.foreground"
	colorContextCache           colorRole = "context.cache"
	colorContextUsed            colorRole = "context.used"
	colorContextFree            colorRole = "context.free"
	colorCursorNormalBright     colorRole = "cursor.normal.bright"
	colorCursorTerminalBright   colorRole = "cursor.terminal.bright"
)

// ColorManager 集中管理 Bubble Tea TUI 的颜色调色板。
type ColorManager struct {
	palette map[colorRole]string
}

// colorManager 是当前 TUI 使用的默认颜色管理器。
var colorManager = NewColorManager()

// NewColorManager 创建默认颜色管理器。
func NewColorManager() ColorManager {
	return ColorManager{
		palette: map[colorRole]string{
			colorTerminalBackground:     "#292C33",
			colorHeaderBackground:       "236",
			colorHeaderForeground:       "231",
			colorLabelUser:              "86",
			colorLabelAssistant:         "111",
			colorLabelTool:              "214",
			colorLabelSystem:            "245",
			colorLabelError:             "203",
			colorBody:                   "252",
			colorMarkdownHeading:        "229",
			colorMarkdownRule:           "240",
			colorMarkdownBullet:         "86",
			colorMarkdownCodeForeground: "230",
			colorMarkdownCodeBackground: "236",
			colorMarkdownCodeBorder:     "62",
			colorMarkdownQuote:          "245",
			colorMarkdownQuoteBorder:    "244",
			colorPanelBorder:            "238",
			colorInputFocusedBorder:     "86",
			colorInputWaitingBorder:     "244",
			colorInputMultilineBorder:   "214",
			colorInputTerminal:          "#ff5ac8",
			colorSelectedProviderBg:     "62",
			colorSelectedProviderFg:     "231",
			colorUnselectedProvider:     "245",
			colorWizardTitle:            "229",
			colorWizardBorder:           "62",
			colorSelectionBackground:    "237",
			colorSelectionForeground:    "255",
			colorContextCache:           "214",
			colorContextUsed:            "111",
			colorContextFree:            "240",
			colorCursorNormalBright:     "#9fffd3",
			colorCursorTerminalBright:   "#ff8ddd",
		},
	}
}

// Hex 返回指定颜色角色对应的 lipgloss 颜色字符串。
func (c ColorManager) Hex(role colorRole) string {
	if c.palette == nil {
		c = NewColorManager()
	}
	return strings.ToLower(c.palette[role])
}

// LipglossColor 返回指定颜色角色对应的 lipgloss.Color。
func (c ColorManager) LipglossColor(role colorRole) lipgloss.Color {
	return lipgloss.Color(c.Hex(role))
}

// CursorColor 根据亮度和终端模式生成光标颜色。
func (c ColorManager) CursorColor(intensity float64, terminal bool) string {
	bright := colorCursorNormalBright
	if terminal {
		bright = colorCursorTerminalBright
	}
	return interpolateHexColor(c.Hex(colorTerminalBackground), c.Hex(bright), clamp01(intensity))
}

// cursorColor 使用当前默认颜色管理器生成光标颜色。
func cursorColor(intensity float64, terminal bool) string {
	return colorManager.CursorColor(intensity, terminal)
}

// interpolateHexColor 在两个十六进制颜色之间按比例插值。
func interpolateHexColor(from, to string, amount float64) string {
	fr, fg, fb := parseHexColor(from)
	tr, tg, tb := parseHexColor(to)
	return fmt.Sprintf(
		"#%02x%02x%02x",
		lerpInt(fr, tr, amount),
		lerpInt(fg, tg, amount),
		lerpInt(fb, tb, amount),
	)
}

// parseHexColor 将 #rrggbb 字符串解析为 RGB 分量。
func parseHexColor(color string) (int, int, int) {
	color = strings.TrimPrefix(color, "#")
	if len(color) != 6 {
		return 0, 0, 0
	}
	r, err := strconv.ParseInt(color[0:2], 16, 0)
	if err != nil {
		return 0, 0, 0
	}
	g, err := strconv.ParseInt(color[2:4], 16, 0)
	if err != nil {
		return 0, 0, 0
	}
	b, err := strconv.ParseInt(color[4:6], 16, 0)
	if err != nil {
		return 0, 0, 0
	}
	return int(r), int(g), int(b)
}

// lerpInt 对整数颜色分量做线性插值。
func lerpInt(from, to int, amount float64) int {
	return from + int(float64(to-from)*amount+0.5)
}

// 本文件定义 Bubble Tea 主界面的布局、输入区渲染和终端光标锚点计算。
package bubble

import (
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/lipgloss"
	"gocode/internal/settings"
)

// View 根据当前状态渲染 header、聊天历史面板和输入面板。
func (m appModel) View() string {
	if !m.ready {
		if m.cursorAnchor != nil {
			m.cursorAnchor.clear()
		}
		return "Starting Bubble Tea..."
	}

	input := m.renderActiveInputPanel()

	var parts []string
	if header := m.renderHeader(); header != "" {
		parts = append(parts, header)
	}
	parts = append(parts, m.renderTranscriptBox())
	if meter := m.renderInputAboveMeter(); meter != "" {
		parts = append(parts, meter)
	}
	parts = append(parts, input)
	view := lipgloss.JoinVertical(lipgloss.Left, parts...)
	m.updateTerminalCursorAnchor(input)
	return view
}

func (m appModel) renderActiveInputPanel() string {
	if m.modelWizard != nil {
		return m.renderModelWizardBox()
	}
	if m.settingWizard != nil {
		return m.renderSettingWizardBox()
	}
	if m.sessionPicker != nil {
		return m.renderSessionPickerBox()
	}
	inputBox := m.renderInputBox()
	if m.completion != nil {
		// 补全弹窗悬浮在输入框上方，输入框始终可见
		return lipgloss.JoinVertical(lipgloss.Left, m.renderCompletionBox(), inputBox)
	}
	return inputBox
}

// updateTerminalCursorAnchor 根据输入框在画面中的位置更新终端真实光标锚点。
func (m appModel) updateTerminalCursorAnchor(inputPanel string) {
	if m.cursorAnchor == nil {
		return
	}
	if !m.shouldAnchorTextInputCursor() {
		m.cursorAnchor.clear()
		return
	}
	m.cursorAnchor.set(m.inputCursorTerminalPosition(inputPanel))
}

// shouldAnchorTextInputCursor 判断当前是否应该把终端真实光标移动到输入单元格。
func (m appModel) shouldAnchorTextInputCursor() bool {
	// 补全弹窗开启时输入框仍然可见，光标仍需锚定
	return m.ready && !m.running && m.modelWizard == nil && m.settingWizard == nil && m.sessionPicker == nil
}

// inputCursorTerminalPosition 计算输入框光标相对当前帧底部的位置。
func (m appModel) inputCursorTerminalPosition(inputPanel string) terminalCursorPosition {
	inputHeight := maxInt(1, lipgloss.Height(inputPanel))
	// 补全弹窗在输入框上方时，光标行需要偏移补全框高度
	completionOffset := 0
	if m.completion != nil {
		completionOffset = lipgloss.Height(m.renderCompletionBox())
	}
	row := minInt(completionOffset+1+m.inputEmbeddedTitleHeight()+visibleTextareaCursorRow(m.input), inputHeight-1)
	upFromBottom := maxInt(0, inputHeight-row-1)
	column := 2 + visibleTextareaCursorColumn(m.input)
	if m.width > 0 {
		column = minInt(column, maxInt(0, m.width-1))
	}
	return terminalCursorPosition{
		active:       true,
		upFromBottom: upFromBottom,
		column:       maxInt(0, column),
	}
}

// inputEmbeddedTitleHeight 返回输入框内部 title 区域的行高。
func (m appModel) inputEmbeddedTitleHeight() int {
	if m.currentSettings().UI.ContextMeterLocation != settings.MeterLocationInputTitle {
		return 0
	}
	width := maxInt(28, m.width-2)
	title := m.contextMeterLine(maxInt(28, width-2))
	return lipgloss.Height(inputLabelStyle.Render(title))
}

// visibleTextareaCursorRow 返回 textarea 光标在当前可视输入区域中的行号。
func visibleTextareaCursorRow(input textarea.Model) int {
	lineInfo := input.LineInfo()
	row := input.Line() + lineInfo.RowOffset
	return minInt(maxInt(0, row), maxInt(0, inputVisibleLineCount(input)-1))
}

// visibleTextareaCursorColumn 返回 textarea 光标在当前可视输入区域中的列号。
func visibleTextareaCursorColumn(input textarea.Model) int {
	return maxInt(0, input.LineInfo().CharOffset)
}

// renderInputBox 渲染普通输入、多行输入、终端输入和等待状态的输入面板。
func (m appModel) renderInputBox() string {
	width := maxInt(28, m.width-2)
	title := ""
	content := m.input.View()
	style := inputPanelFocusedStyle
	titleStyle := inputLabelStyle
	if m.currentSettings().UI.ContextMeterLocation == settings.MeterLocationInputTitle {
		title = m.contextMeterLine(maxInt(28, width-2))
	}

	if m.isTerminalInputActive() {
		style = inputPanelTerminalStyle
	}
	if m.hasMultilineInput() {
		style = inputPanelMultilineStyle
		if m.isTerminalInputActive() {
			style = inputPanelTerminalStyle
		}
	}
	if m.running {
		content = inputWaitingStyle.Render("waiting for assistant...")
		style = inputPanelWaitingStyle
		if m.runningTerminal {
			content = inputWaitingStyle.Render("running shell command...")
			style = inputPanelTerminalStyle
		}
	}

	body := content
	if title != "" {
		body = lipgloss.JoinVertical(lipgloss.Left, titleStyle.Render(title), content)
	}
	return style.Width(width).Render(body)
}

// renderTranscriptBox 渲染带边框的聊天历史滚动面板。
func (m appModel) renderTranscriptBox() string {
	width := maxInt(28, m.width-2)
	return transcriptPanelStyle.Width(width).Height(maxInt(1, m.viewport.Height)).Render(m.viewport.View())
}

// renderHeader 渲染顶部状态栏。空 header 文本表示当前不展示状态栏。
func (m appModel) renderHeader() string {
	text := m.headerText()
	if text == "" {
		return ""
	}
	return headerStyle.Width(m.width).Render(text)
}

// headerHeight 返回当前布局中 header 实际占用的高度。
func (m appModel) headerHeight() int {
	return lipgloss.Height(m.renderHeader())
}

// headerText 生成顶部状态栏文本。
// TODO: 后期希望改成显示时间或者用标签页方式展示 agent 的状态。
func (m appModel) headerText() string {
	if m.currentSettings().UI.ContextMeterLocation == settings.MeterLocationHeader {
		return m.contextMeterLine(maxInt(28, m.width))
	}
	return ""
}

func (m appModel) renderInputAboveMeter() string {
	if m.currentSettings().UI.ContextMeterLocation != settings.MeterLocationInputAbove {
		return ""
	}
	width := maxInt(28, m.width-2)
	return inputLabelStyle.Width(width).Render(m.contextMeterLine(width))
}

// relayout 根据终端尺寸和输入高度重新计算 viewport 与 textarea 尺寸。
func (m *appModel) relayout() {
	width := maxInt(20, m.width)
	m.viewport.Width = maxInt(20, width-transcriptPanelHorizontalFrame)
	m.input.SetWidth(maxInt(20, width-4))
	m.input.SetHeight(inputVisibleLineCount(m.input))
	headerHeight := m.headerHeight()
	inputHeight := lipgloss.Height(m.renderActiveInputPanel())
	inputAboveHeight := lipgloss.Height(m.renderInputAboveMeter())
	availableTranscriptHeight := m.height - headerHeight - inputAboveHeight - inputHeight - transcriptPanelVerticalFrame
	m.viewport.Height = maxInt(1, availableTranscriptHeight)
	m.expandTranscriptToFillHeight()
}

func (m *appModel) expandTranscriptToFillHeight() {
	if m.height <= 0 {
		return
	}
	input := m.renderActiveInputPanel()
	var parts []string
	if header := m.renderHeader(); header != "" {
		parts = append(parts, header)
	}
	parts = append(parts, m.renderTranscriptBox())
	if meter := m.renderInputAboveMeter(); meter != "" {
		parts = append(parts, meter)
	}
	parts = append(parts, input)
	if deficit := m.height - lipgloss.Height(lipgloss.JoinVertical(lipgloss.Left, parts...)); deficit > 0 {
		m.viewport.Height += deficit
	}
}

// 本文件定义 Bubble Tea TUI 对外暴露的 UI 适配器。
package bubble

import (
	"context"
	"errors"
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
	"gocode/internal/message"
	"gocode/internal/model"
	"gocode/internal/session"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"gocode/internal/ui"
	"os"
	"sync"
)

// Runner 描述 TUI 提交一轮用户输入时需要调用的对话运行器。
type Runner interface {
	RunTurn(ctx context.Context, input string) (message.Message, error)
	ResetHistory()
	LoadHistory(ctx context.Context, sessionID string) error
}

// SessionStore 描述 TUI 列举和管理会话所需的最小接口。
type SessionStore interface {
	ListSessions(ctx context.Context) ([]session.SessionSummary, error)
}

// ModelConfigController 描述运行时读取和应用模型配置的控制器。
type ModelConfigController interface {
	CurrentModelConfig() model.Config
	ApplyModelConfig(model.Config) error
}

// ModelConfigSaver 描述可将模型配置持久化到磁盘的控制器扩展。
type ModelConfigSaver interface {
	SaveModelConfig(model.Config) error
}

// SettingsController 描述运行时读取和保存 UI/agent 设置的控制器。
type SettingsController interface {
	CurrentSettings() settings.Config
	SaveSettings(settings.Config) error
}

// SubagentController 描述 TUI 手动启动和查看 subagent 所需的能力。
type SubagentController interface {
	Run(context.Context, subagent.Request) (subagent.Result, error)
	Launch(context.Context, subagent.Request) (subagent.TaskSnapshot, error)
	ListTasks() []subagent.TaskSnapshot
}

// UI 是基于 Bubble Tea 的交互式终端界面实现。
type UI struct {
	mu                    sync.Mutex
	program               *tea.Program
	modelConfigController ModelConfigController
	settingsController    SettingsController
	subagentController    SubagentController
	sessionStore          SessionStore
}

// 确保 UI 满足通用终端 UI 接口。
var _ ui.UI = (*UI)(nil)

// New 创建一个尚未启动的 Bubble Tea UI 实例。
func New() *UI {
	return &UI{}
}

// SetModelConfigController 注入模型配置控制器，供 /model 向导读取和保存配置。
func (u *UI) SetModelConfigController(controller ModelConfigController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.modelConfigController = controller
}

// SetSettingsController 注入 settings 控制器，供 /setting 和状态栏读取。
func (u *UI) SetSettingsController(controller SettingsController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.settingsController = controller
}

// SetSubagentController 注入 subagent 控制器，供 /subagent 和 /tasks 使用。
func (u *UI) SetSubagentController(controller SubagentController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.subagentController = controller
}

// SetSessionStore 注入 session store，供 /sessions 命令列举历史会话。
func (u *UI) SetSessionStore(store SessionStore) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.sessionStore = store
}

// Run 启动 Bubble Tea 主循环，并把输出写入带光标锚点修正的终端流。
func (u *UI) Run(ctx context.Context, runner Runner, sessionID string) error {
	u.mu.Lock()
	controller := u.modelConfigController
	settingsController := u.settingsController
	subagentController := u.subagentController
	sessionStore := u.sessionStore
	u.mu.Unlock()

	anchor := newTerminalCursorAnchor()
	appModel := newModel(ctx, runner, sessionID, controller, settingsController, subagentController, sessionStore, anchor)
	program := tea.NewProgram(
		appModel,
		tea.WithContext(ctx),
		tea.WithOutput(newAnchoredOutput(os.Stdout, anchor)),
		tea.WithMouseCellMotion(),
	)

	u.mu.Lock()
	u.program = program
	u.mu.Unlock()

	_, err := program.Run()

	u.mu.Lock()
	if u.program == program {
		u.program = nil
	}
	u.mu.Unlock()

	if errors.Is(err, tea.ErrInterrupted) {
		return nil
	}
	return err
}

// OnAssistantDelta 接收模型流式文本增量，并转发给 Bubble Tea 状态机。
func (u *UI) OnAssistantDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(assistantDeltaMsg(text))
}

